import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { parseIsa, VALIDATOR_REGISTRY } from './tools/kad/isa.mjs';
const base = 'docs/gaya/dataset-generation/';
const plan = JSON.parse(readFileSync(base + 'workpackages.json', 'utf8'));
const isa = parseIsa(readFileSync(base + 'ISA-GAYA-DATASET-G1-001.md', 'utf8'));
const md = readFileSync(base + 'WORKPACKAGES.md', 'utf8');
assert.equal(plan.native_workctl_registered, false);
assert.equal(plan.workpackages.length, 10);
assert.equal(isa.claims.length, 11);
assert.equal(isa.metadata.status, 'DRAFT_VALIDATOR_BINDING_PENDING');
assert.equal(isa.metadata.train_eligible, 'false');
const ids = new Set(plan.workpackages.map(f => f.id));
assert.equal(ids.size, 10);
const claims = new Set(isa.claims.map(c => c.id));
assert.equal(claims.size, 11);
const complete = new Set();
const covered = new Set();
for (const f of plan.workpackages) {
  assert.equal(f.status, 'PROPOSED');
  assert.equal(f.fixed_point, null);
  for (const d of f.depends_on) { assert.ok(ids.has(d)); assert.ok(complete.has(d)); }
  for (const key of ['inputs','owned_paths','non_goals','steps','acceptance','proof','stop','research','gates']) assert.ok(Array.isArray(f[key]) && f[key].length > 0, f.id + ':' + key);
  for (const g of f.gates) { assert.ok(claims.has(g), g); covered.add(g); }
  assert.equal(md.split('### ' + f.id + ' — ').length - 1, 1);
  assert.ok(f.steps.every(step => md.includes(step)));
  complete.add(f.id);
}
assert.equal(covered.size, claims.size);
for (const c of isa.claims) { assert.equal(c.status, 'PENDING'); assert.equal(c.target_state, 'CANONICAL_TARGET'); assert.equal(VALIDATOR_REGISTRY[c.validator], undefined); }
console.log(JSON.stringify({handoff_integrity:'PASS', workpackages:ids.size, claims:claims.size, all_claims_covered:true, dag:'ACYCLIC_TOPologically_ORDERED', markdown_frame_mirror:'EXACT_STEPS', native_registration:'NOT_PERFORMED', native_validator_bindings:'11_PLANNED_UNREGISTERED', implementation_acceptance:'NOT_CLAIMED'}, null, 2));
